def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_prev_bids = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if isinstance(prev, dict) else None
            if bid is not None:
                prev_bids.append(float(bid))
                opp_hp = opp.get('hp', 10)
                opp_nwd = opp.get('no_water_days', 0)
                if opp_hp <= 4 or opp_nwd >= 1:
                    urgent_prev_bids.append(float(bid))

    if not alive:
        return float(min(budget, 8.0))

    competitor_count = len(alive)
    tight_supply = supply <= 16.0
    ample_supply = supply >= 22.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_high = max(urgent_prev_bids) if urgent_prev_bids else highest_prev

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2
    if tight_supply:
        danger += 1

    if danger >= 5:
        bid = max(urgent_high + 3.0, DAILY_SALARY * 1.18)
    elif danger >= 3:
        bid = max(urgent_high + 1.5, DAILY_SALARY * 0.92)
    elif danger >= 2:
        bid = max(highest_prev * 0.78, DAILY_SALARY * 0.62)
    else:
        if ample_supply:
            bid = DAILY_SALARY * 0.34
        elif highest_prev >= 140:
            bid = DAILY_SALARY * 0.36
        elif highest_prev >= 100:
            bid = DAILY_SALARY * 0.48
        else:
            bid = max(DAILY_SALARY * 0.42, highest_prev * 0.58)

    if competitor_count >= 3 and danger <= 2 and highest_prev >= 120:
        bid *= 0.9
    if day >= 8 and hp >= 6 and no_water == 0 and budget < 250:
        bid *= 0.85
    if day <= 2 and hp >= 8 and no_water == 0 and ample_supply:
        bid *= 0.9

    reserve = 0.0
    if hp > 4 and no_water == 0:
        reserve = DAILY_SALARY * 1.2
    elif hp > 2:
        reserve = DAILY_SALARY * 0.5

    cap = max(0.0, budget - reserve)
    if danger >= 3:
        cap = budget

    bid = min(bid, cap if cap > 0 else budget)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Read only yesterday's immediate pressure signal from previous_trace
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply pressure: if supply is close to our requirement, we must bid more to ensure allocation
    # Convert to an integer estimate of how many full water units could be funded in aggregate.
    # (We only use it as a heuristic; indices are not used.)
    supply_ratio = supply / float(WATER_REQ)

    # Base willingness to pay
    # If opponents were bidding high yesterday, we slightly increase to avoid being outbid.
    base = DAILY_SALARY * 0.55

    if highest_prev_bid >= DAILY_SALARY * 0.85:
        base = DAILY_SALARY * 0.65
    elif highest_prev_bid >= DAILY_SALARY * 0.65:
        base = DAILY_SALARY * 0.60

    # Tight supply -> increase
    if supply_ratio < 2.0:
        base *= 1.15
    elif supply_ratio < 2.5:
        base *= 1.05

    # If I'm in danger, bid more aggressively
    if hp <= 2 or no_water_days >= 2:
        base *= 1.35
    elif hp <= 3:
        base *= 1.15

    # Cap by budget and also avoid overcommitting when budget is low
    # Keep some reserve for later days.
    reserve_fraction = 0.25
    max_affordable = max(0.0, budget * (1.0 - reserve_fraction))

    # If budget is extremely low, bid just enough to extend survival
    if budget < DAILY_SALARY * 0.6:
        if hp <= 2:
            bid = min(budget, DAILY_SALARY * 0.9)
        else:
            bid = min(budget, DAILY_SALARY * 0.6)
        return float(bid)

    # Otherwise, bid around base, with a small nudge above the highest_prev_bid only when needed
    # (We don't know today's bids, so we use a conservative nudge.)
    nudge = 0.0
    if highest_prev_bid > 0:
        # If yesterday's highest bid was very high, match partially.
        if highest_prev_bid >= DAILY_SALARY * 1.0:
            nudge = DAILY_SALARY * 0.08
        elif highest_prev_bid >= DAILY_SALARY * 0.85:
            nudge = DAILY_SALARY * 0.05

    bid = base + nudge

    # Ensure within bounds
    bid = min(bid, max_affordable)
    bid = max(0.0, bid)

    # If we still bid too low relative to yesterday's top, slightly increase.
    if highest_prev_bid > 0 and bid < highest_prev_bid * 0.75 and hp <= 4:
        bid = min(max_affordable, highest_prev_bid * 0.8)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 70

    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], DAILY_SALARY * 1.2)
    elif supply < 18:
        bid = min(my_status['budget'], max(avg_prev_bid * 1.05, DAILY_SALARY * 0.8))
    else:
        bid = min(my_status['budget'], max(avg_prev_bid * 0.9, DAILY_SALARY * 0.6))

    return float(bid)
